corrected_code:
package support

import (
	"context"
	"gorm.io/gorm"
	"myapp/auth"
	"myapp/models"
)

type TicketService struct {
	DB *gorm.DB
}

func (ts *TicketService) ListCustomTags(ctx context.Context, ticketID string) ([]models.TicketTag, error) {
	var tags []models.TicketTag
	tenantID := auth.GetTenantID(ctx)

	err := ts.DB.WithContext(ctx).
		Joins("JOIN support_tickets ON support_tickets.id = ticket_tags.ticket_id").
		Where("ticket_tags.ticket_id = ? AND support_tickets.tenant_id = ?", ticketID, tenantID).
		Find(&tags).Error
	if err != nil {
		return nil, err
	}

	return tags, nil
}
